import { useEffect, useState } from "react";
import { Link } from "react-router-dom";

import Layout from "./Layout.jsx";

function Dashboard({ search, setSearch }) {
  const [questions, setQuestions] = useState([]);
  const [notes, setNotes] = useState([]);
  const [filter, setFilter] = useState("recent");
  const [category, setCategory] = useState("all");
  const [activeTab, setActiveTab] = useState("posts");

  const [noteQuestions, setNoteQuestions] = useState({});
  const [questionCounts, setQuestionCounts] = useState({});

  const user = JSON.parse(localStorage.getItem("user") || "null");

  // ===============================
  // GET QUESTIONS
  // ===============================
  const loadQuestions = () => {
    fetch("http://localhost:5000/api/questions")
      .then((res) => res.json())
      .then((data) => setQuestions(data))
      .catch((err) => console.log(err));
  };

  // ===============================
  // GET NOTES
  // ===============================
  const loadNotes = () => {
    fetch("http://localhost:5000/api/notes")
      .then((res) => res.json())
      .then((data) => {
        setNotes(data);

        // Get question count for every note
        data.forEach((note) => {
          fetch(
            `http://localhost:5000/api/notes/${note._id}/questions`
          )
            .then((res) => res.json())
            .then((questions) => {
              setQuestionCounts((prev) => ({
                ...prev,
                [note._id]: questions.length,
              }));
            })
            .catch((err) => console.log(err));
        });
      })
      .catch((err) => console.log(err));
  };

  useEffect(() => {
    loadQuestions();
    loadNotes();
  }, []);

  // ===============================
  // FILTER QUESTIONS
  // ===============================
  const filtered = questions
    .filter((q) => {
      const searchText = search?.toLowerCase() || "";

      const matchesSearch =
        q.title?.toLowerCase().includes(searchText) ||
        q.description?.toLowerCase().includes(searchText) ||
        q.category?.toLowerCase().includes(searchText);

      const matchesCategory =
        category === "all" ? true : q.category === category;

      return matchesSearch && matchesCategory;
    })
    .sort((a, b) => {
      if (filter === "recent") {
        return new Date(b.createdAt) - new Date(a.createdAt);
      }

      if (filter === "popular") {
        return (b.views || 0) - (a.views || 0);
      }

      return 0;
    });

  // ===============================
  // FILTER NOTES
  // ===============================
  const filteredNotes = notes.filter((note) => {
    const s = search?.toLowerCase() || "";

    return (
      note.title?.toLowerCase().includes(s) ||
      note.topic?.toLowerCase().includes(s) ||
      note.uploadedBy?.toLowerCase().includes(s)
    );
  });

  // ===============================
  // ASK QUESTION ABOUT NOTE
  // ===============================
  const handleNoteQuestion = async (note) => {
    const question = noteQuestions[note._id];

    if (!question?.trim()) {
      alert("Please type your question first");
      return;
    }

    try {
      const res = await fetch(
        `http://localhost:5000/api/notes/${note._id}/questions`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            title: question,
            description: `Question about note: "${note.title}"`,
            postedBy: user?.name,
            role: user?.role,
          }),
        }
      );

      const data = await res.json();

      if (res.ok) {
        alert("Question sent to the note owner! 💬");

        setNoteQuestions((prev) => ({
          ...prev,
          [note._id]: "",
        }));

        setQuestionCounts((prev) => ({
          ...prev,
          [note._id]: (prev[note._id] || 0) + 1,
        }));

      } else {
        alert(data.message || "Failed to ask question");
      }

    } catch (err) {
      console.error(err);
      alert("Server error");
    }
  };

  return (
    <Layout
      filter={filter}
      setFilter={setFilter}
      category={category}
      setCategory={setCategory}
      search={search}
      setSearch={setSearch}
    >

      {/* ================= HEADER ================= */}

      <div className="header">

        <div>
          <h2>
            {activeTab === "posts" ? "All Posts" : "Study Notes"}
          </h2>

          <p>
            {activeTab === "posts"
              ? `${filtered.length} posts available`
              : `${filteredNotes.length} notes available`}
          </p>
        </div>

        <Link to="/ask" className="new-post">
          + New Post
        </Link>

      </div>


      {/* ================= TABS ================= */}

      <div
        style={{
          display: "flex",
          gap: "8px",
          marginBottom: "20px",
        }}
      >

        <button
          onClick={() => setActiveTab("posts")}
          style={{
            padding: "10px 25px",
            borderRadius: "9px",
            border: "none",
            cursor: "pointer",
            fontWeight: "600",
            background:
              activeTab === "posts"
                ? "#4caf68"
                : "#e9efeb",
            color:
              activeTab === "posts"
                ? "white"
                : "#526058",
          }}
        >
          📋 Posts
        </button>


        <button
          onClick={() => setActiveTab("notes")}
          style={{
            padding: "10px 25px",
            borderRadius: "9px",
            border: "none",
            cursor: "pointer",
            fontWeight: "600",
            background:
              activeTab === "notes"
                ? "#4caf68"
                : "#e9efeb",
            color:
              activeTab === "notes"
                ? "white"
                : "#526058",
          }}
        >
          📚 Notes
        </button>

      </div>


      {/* =====================================================
          POSTS
      ===================================================== */}

      {activeTab === "posts" && (

        <div>

          {filtered.length === 0 ? (

            <div className="card">
              <p>No posts available.</p>
            </div>

          ) : (

            filtered.map((q) => (

              <div key={q._id} className="post">

                <div className="post-top">

                  <div className="user">

                    <div className="avatar small">
                      {q.postedBy?.[0]?.toUpperCase() || "U"}
                    </div>

                    <div>
                      <b>{q.postedBy}</b>

                      <p
                        style={{
                          margin: 0,
                          fontSize: "12px",
                        }}
                      >
                        {q.role}
                      </p>
                    </div>

                  </div>

                  <span className="tag">
                    {q.category}
                  </span>

                </div>


                <h3>{q.title}</h3>

                <p
                  style={{
                    color: "#68756d",
                    marginBottom: "15px",
                  }}
                >
                  {q.description}
                </p>


                <div className="post-bottom">

                  <span>
                    ❤️ {q.likes?.length || 0}
                  </span>

                  <Link
                    to={`/answers/${q._id}`}
                    className="view-btn"
                  >
                    View →
                  </Link>

                </div>

              </div>

            ))
          )}

        </div>

      )}


      {/* =====================================================
          NOTES
      ===================================================== */}

      {activeTab === "notes" && (

        <div>

          {filteredNotes.length === 0 ? (

            <div className="card">
              <p>No notes available.</p>
            </div>

          ) : (

            filteredNotes.map((note) => (

              <div key={note._id} className="post">

                {/* NOTE HEADER */}

                <div className="post-top">

                  <div className="user">

                    <div className="avatar small">
                      {note.uploadedBy?.[0]?.toUpperCase() || "U"}
                    </div>

                    <div>

                      <b>{note.uploadedBy}</b>

                      <p
                        style={{
                          margin: 0,
                          fontSize: "12px",
                        }}
                      >
                        Senior
                      </p>

                    </div>

                  </div>

                  <span className="tag">
                    {note.topic}
                  </span>

                </div>


                {/* NOTE TITLE */}

                <h3>
                  📄 {note.title}
                </h3>


                {/* DOWNLOAD + QUESTIONS */}

                <div className="post-bottom">

                  <a
                    href={`http://localhost:5000/uploads/${note.file}`}
                    target="_blank"
                    rel="noreferrer"
                    className="view-btn"
                  >
                    📥 Download Note
                  </a>

                  <span>
                    💬 {questionCounts[note._id] || 0} Questions
                  </span>

                </div>


                {/* ASK QUESTION */}

                <div
                  style={{
                    marginTop: "18px",
                    paddingTop: "16px",
                    borderTop: "1px solid #edf1ee",
                  }}
                >

                  <p
                    style={{
                      margin: "0 0 9px",
                      fontSize: "13px",
                      fontWeight: "600",
                      color: "#526058",
                    }}
                  >
                    💬 Have a question about this note?
                  </p>


                  <div
                    style={{
                      display: "flex",
                      gap: "9px",
                    }}
                  >

                    <input
                      type="text"
                      placeholder="Ask the note owner..."
                      value={noteQuestions[note._id] || ""}
                      onChange={(e) =>
                        setNoteQuestions((prev) => ({
                          ...prev,
                          [note._id]: e.target.value,
                        }))
                      }
                      style={{
                        flex: 1,
                        padding: "10px 12px",
                        borderRadius: "8px",
                        border: "1px solid #dbe4de",
                        outline: "none",
                      }}
                    />

                    <button
                      onClick={() => handleNoteQuestion(note)}
                      style={{
                        padding: "10px 18px",
                        background: "#4caf68",
                        color: "white",
                        border: "none",
                        borderRadius: "8px",
                        cursor: "pointer",
                        fontWeight: "600",
                      }}
                    >
                      Ask
                    </button>

                  </div>

                </div>

              </div>

            ))
          )}

        </div>

      )}

    </Layout>
  );
}

export default Dashboard;
